function styleHeaderRow(sheet, headers) {
  sheet.getRange(1, 1, 1, headers.length)
    .setFontWeight('bold')
    .setBackground('#1e293b')
    .setFontColor('#ffffff');
  sheet.setFrozenRows(1);
}

